import java.util.ArrayList;
import java.util.List;

public class Main {
    class Solution {
        public static int countChar(String str, char target) {
            int count = 0;
            for (int i = 0; i < str.length(); i++) {
                if (str.charAt(i) == target) {
                    count++;
                }
            }
            return count;
        }

        public static char findTheDifference(String s, String t) {
            List<Character> save = new ArrayList<>();
            int max = t.length();
            char search;

            for(int i = 0; i < max; i++) {
                search = t.charAt(i);

                if(save.indexOf(search) != -1)
                    continue;

                if(countChar(t, search) != countChar(s, search))
                    return search;

                //System.out.printf("t - %c : %d \n", search, countChar(t, search));
                //System.out.printf("s - %c : %d \n", search, countChar(s, search));

                save.add(t.charAt(i));
            }

            return '-';
        }
    }

    public static void main(String[] args) {
        System.out.println(Solution.findTheDifference("abcd", "abcde"));
        System.out.println(Solution.findTheDifference("", "y"));
        System.out.println(Solution.findTheDifference("a", "aa"));
        System.out.println(Solution.findTheDifference("", ""));
    }
}